let rawText = $input.first().json.output || "";

/**
 * FUNGSI PEMBERSIH UTAMA (Bracket Counter Logic)
 * Fungsi ini membersihkan log [Used tools: ...]
 */
function removeSmartly(text, startMarker) {
    if (!text.includes(startMarker)) return text;

    let startIndex = text.indexOf(startMarker);
    let depth = 0;
    let foundStart = false;
    let endIndex = -1;

    for (let i = startIndex; i < text.length; i++) {
        if (text[i] === '[') {
            depth++;
            foundStart = true;
        } else if (text[i] === ']') {
            depth--;
        }

        if (foundStart && depth === 0) {
            endIndex = i;
            break; 
        }
    }

    if (endIndex !== -1) {
        let remainingText = text.substring(endIndex + 1);
        return removeSmartly(remainingText, startMarker);
    }

    return text;
}

// 2. Jalankan pembersihan Cerdas (Hapus Tools Log)
rawText = removeSmartly(rawText, "[Used tools:");

// 3. TAHAP FINAL: Hapus sisa-sisa artifact 
rawText = rawText.replace(/^[\s\}\]"]+/g, '');

// 4. Hapus artifact JSON spesifik n8n
rawText = rawText.replace(/\{"to":.*?\}/g, '');

// ============================================================
// 5. LANGKAH BARU: FORMATTING KHUSUS WHATSAPP
//    (Mengubah HTML/Markdown menjadi WA Style)
// ============================================================

// A. Handle Newlines HTML (<br> dan </p>)
rawText = rawText.replace(/<br\s*\/?>/gi, '\n');
rawText = rawText.replace(/<\/p>/gi, '\n\n');
rawText = rawText.replace(/<p>/gi, '');

// B. Ubah Header Markdown (### Judul) menjadi *JUDUL* (Tebal & Kapital)
//    WA tidak punya heading, jadi kita akali dengan huruf kapital tebal
rawText = rawText.replace(/^#{1,6}\s+(.*)$/gm, (match, p1) => {
    return `*${p1.toUpperCase()}*`;
});

// C. Ubah BOLD: 
//    HTML (<b>, <strong>) & Markdown (**) -> WhatsApp (*)
rawText = rawText.replace(/<b>(.*?)<\/b>/gi, '*$1*');
rawText = rawText.replace(/<strong>(.*?)<\/strong>/gi, '*$1*');
rawText = rawText.replace(/\*\*(.*?)\*\*/g, '*$1*');

// D. Ubah ITALIC: 
//    HTML (<i>, <em>) -> WhatsApp (_)
rawText = rawText.replace(/<i>(.*?)<\/i>/gi, '_$1_');
rawText = rawText.replace(/<em>(.*?)<\/em>/gi, '_$1_');

// E. Ubah MONOSPACE/CODE: 
//    HTML (<pre>, <code>) & Markdown (`) -> WhatsApp (```)
rawText = rawText.replace(/<pre>(.*?)<\/pre>/gs, '```$1```');
rawText = rawText.replace(/<code>(.*?)<\/code>/g, '```$1```');
rawText = rawText.replace(/`(.*?)`/g, '```$1```');

// F. Ubah List HTML (<li>) menjadi strip biasa
rawText = rawText.replace(/<li>(.*?)<\/li>/gi, '- $1\n');
rawText = rawText.replace(/<\/?ul>/gi, '');
rawText = rawText.replace(/<\/?ol>/gi, '');

// G. Bersihkan tag HTML lain yang tersisa (misal <span>, <div>)
rawText = rawText.replace(/<[^>]*>/g, '');

// ============================================================

// 6. Trim spasi kosong akhir
const cleanText = rawText.trim();

return {
  json: {
    text: cleanText
  }
};

// 1. Ambil Timestamp dari Payload WAHA
const item = $input.first();
const json = item.json;

// Ambil raw timestamp (bisa dari payload.timestamp atau timestamp langsung)
let rawTimestamp = json.payload?.timestamp || json.timestamp || 0;

// 2. NORMALISASI: Ubah SEMUA ke satuan DETIK
// Logika: Jika angkanya besar sekali (lebih dari tahun 2286 dalam detik), pasti itu Milidetik.
// Angka 10000000000 adalah batas aman (11 digit).
let normalizedMsgTime = Number(rawTimestamp);

if (normalizedMsgTime > 10000000000) {
  // Jika 13 digit (Milidetik), bagi 1000 agar jadi Detik
  normalizedMsgTime = Math.floor(normalizedMsgTime / 1000);
}

// 3. Ambil Waktu Server Sekarang (dalam Detik)
const serverTime = Math.floor(Date.now() / 1000);

// 4. Hitung Umur Pesan (Selisih dalam Detik)
const ageInSeconds = serverTime - normalizedMsgTime;

// 5. Tentukan Batas Toleransi
// Toleransi: Pesan dianggap basi jika lebih tua dari 120 detik (2 menit)
// Toleransi Future: Pesan dianggap aneh jika dari masa depan > 10 detik (beda jam server)
const isTooOld = ageInSeconds > 120;
const isFuture = ageInSeconds < -10; 

// Logika Stop
let expired = false;
let reason = "New message";

if (isTooOld) {
  expired = true;
  reason = `Message too old (Age: ${ageInSeconds}s)`;
} else if (isFuture) {
  expired = true;
  reason = `Message from future (Diff: ${ageInSeconds}s)`;
}

// Return data beserta Debug Info agar Anda bisa cek
return { 
  json: { 
    ...json, 
    expired: expired,
    debug_filter: {
      status: expired ? "BLOCKED" : "ALLOWED",
      reason: reason,
      time_of_msg_original: rawTimestamp,        // 1770871132851 in millisecs
      time_of_msg_normalized: normalizedMsgTime, // 1770871132 in secs (Sudah dipotong)
      time_of_server: serverTime,                // 1770871347
      age_in_seconds: ageInSeconds                  // 215
    }
  } 
};

// 1. Ambil output mentah
let rawText = $input.first().json.output || "";

/**
 * FUNGSI PEMBERSIH UTAMA (Bracket Counter Logic)
 * Fungsi ini menghitung jumlah kurung buka '[' dan tutup ']'
 * untuk mencari pasangan penutup yang SEBENARNYA, bukan yang di tengah jalan.
 */
function removeSmartly(text, startMarker) {
    if (!text.includes(startMarker)) return text;

    let startIndex = text.indexOf(startMarker);
    let depth = 0;
    let foundStart = false;
    let endIndex = -1;

    // Scan karakter satu per satu mulai dari posisi marker
    for (let i = startIndex; i < text.length; i++) {
        if (text[i] === '[') {
            depth++;
            foundStart = true;
        } else if (text[i] === ']') {
            depth--;
        }

        // Jika depth kembali ke 0 (artinya semua kurung buka sudah ditutup)
        if (foundStart && depth === 0) {
            endIndex = i;
            break; 
        }
    }

    // Jika blok sampah ditemukan dan tertutup sempurna
    if (endIndex !== -1) {
        // Ambil sisa teks SETELAH blok sampah
        let remainingText = text.substring(endIndex + 1);
        // Cek lagi secara rekursif (siapa tahu ada 2 blok Used Tools)
        return removeSmartly(remainingText, startMarker);
    }

    return text;
}

// 2. Jalankan pembersihan Cerdas
rawText = removeSmartly(rawText, "[Used tools:");

// 3. TAHAP FINAL: Hapus sisa-sisa artifact (jika ada spasi/simbol tertinggal di awal)
// Regex ini membersihkan jika masih ada sisa "}]" atau tanda kutip di awal kalimat jawaban
rawText = rawText.replace(/^[\s\}\]"]+/g, '');

// 4. Hapus artifact JSON spesifik n8n yang kadang bandel
rawText = rawText.replace(/\{"to":.*?\}/g, '');

// 5. Trim spasi kosong
const cleanText = rawText.trim();

return {
  json: {
    output: cleanText
  }
};

